const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

require('input_field')
require('button')

module.exports = wallet_setup

async function wallet_setup(opts = {}, protocol) {
  const { sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: onicons }
  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="wallet-setup">
      <section class="loading-view" data-view="loading"><span class="loading-ring"></span><p>Checking wallet…</p></section>

      <section class="loaded-view hidden" data-view="loaded">
        <header class="page-header">
          <p class="eyebrow">Security & recovery</p>
          <h1>Wallet Setup</h1>
          <p class="page-copy">Keep access to your wallet, channels, and funds.</p>
        </header>

        <div class="current-wallet">
          <span class="status-icon">✓</span>
          <div class="current-wallet-details">
            <span class="card-caption">Wallet connected</span>
            <strong class="current-wallet-alias">Loading wallet alias…</strong>
            <div class="current-node-row">
              <span class="current-node-id">Loading node ID…</span>
              <button class="current-node-copy" data-action="copy-node-id" aria-label="Copy node ID">Copy</button>
            </div>
          </div>
          <span class="active-badge">Active</span>
        </div>

        <div class="section-title">
          <div><span class="step-label">Wallet recovery</span><h2>Choose what to back up</h2></div>
          <span class="progress-label">0 of 2 saved</span>
        </div>

        <div class="setup-options">
          <article class="option-shell mnemonic-option">
            <button class="option-card" data-action="toggle-mnemonic" aria-expanded="false">
              <span class="option-icon phrase-icon">•••</span>
              <span class="option-content"><strong>Recovery phrase</strong><small>View and securely save your 12 recovery words.</small></span>
              <span class="option-state hidden">Saved</span><span class="chevron">›</span>
            </button>
            <div class="option-detail mnemonic-detail hidden">
              <div class="security-note"><span>!</span><p>Anyone with these words can control your wallet. Keep them private and offline.</p></div>
              <textarea class="mnemonic-text" readonly placeholder="Loading recovery phrase…"></textarea>
              <div class="button-row">
                <button class="secondary-button mnemonic-action" data-action="copy-mnemonic" disabled>Copy phrase</button>
                <button class="secondary-button mnemonic-action" data-action="download-mnemonic" disabled>Save phrase</button>
              </div>
              <div class="inline-status hidden mnemonic-status" role="status"></div>
            </div>
          </article>

          <article class="option-shell scb-option">
            <button class="option-card" data-action="download-scb">
              <span class="option-icon file-icon">↓</span>
              <span class="option-content"><strong>Channel backup</strong><small>Download your latest Static Channel Backup file.</small></span>
              <span class="option-state hidden">Saved</span><span class="file-badge">SCB</span>
            </button>
            <div class="inline-status hidden scb-status" role="status"></div>
          </article>

          <article class="option-shell drain-option">
            <button class="option-card" data-action="toggle-drain" aria-expanded="false">
              <span class="option-icon drain-icon">↗</span>
              <span class="option-content"><strong>Drain funds</strong><small>Close channels and move funds to a safe address.</small></span>
              <span class="chevron">›</span>
            </button>
            <div class="option-detail drain-detail hidden">
              <div class="security-note danger-note"><span>!</span><p>This is an emergency action. Channel closures may take time and incur network fees.</p></div>
              <label class="field-label" for="drain-address">Safe Bitcoin address</label>
              <input id="drain-address" class="address-input" type="text" placeholder="bc1q…" autocomplete="off">
              <button class="danger-outline-button" data-action="drain-funds">Drain all funds</button>
              <div class="inline-status hidden drain-status" role="status"></div>
            </div>
          </article>
        </div>

        <section class="exit-section">
          <div class="exit-heading"><span class="exit-icon">↪</span><div><h2>Exit this wallet</h2><p>Remove this wallet from this device when you are finished.</p></div></div>
          <div class="backup-advice"><span>!</span><p><strong>Back up before you exit.</strong> Save your recovery phrase and channel backup so you can recover later.</p></div>
          <button class="danger-text-button" data-action="show-delete">Exit and delete wallet</button>
          <div class="delete-confirmation hidden">
            <div><strong>Delete wallet from this device?</strong><p>This cannot be undone here. Your backups are the only way to recover it.</p></div>
            <div class="button-row"><button class="secondary-button" data-action="cancel-delete">Cancel</button><button class="danger-button" data-action="confirm-delete">Delete wallet</button></div>
          </div>
        </section>
      </section>

      <section class="empty-view hidden" data-view="empty">
        <header class="page-header"><p class="eyebrow">Wallet setup</p><h1>Set up your wallet</h1></header>
        <div class="empty-hero"><span class="empty-wallet-icon">◇</span><h2>No wallet found</h2><p>Create a new wallet or bring back one you already own.</p></div>
        <div class="setup-options empty-options">
          <button class="option-card featured-card" data-action="create-wallet">
            <span class="option-icon new-wallet-icon">+</span>
            <span class="option-content"><strong>Create new wallet</strong><small>Get a fresh wallet and recovery phrase instantly.</small></span><span class="chevron">›</span>
          </button>
          <button class="option-card" data-action="import-wallet">
            <span class="option-icon import-icon">↓</span>
            <span class="option-content"><strong>Import existing wallet</strong><small>Restore a wallet using your recovery details.</small></span><span class="chevron">›</span>
          </button>
        </div>
        <div class="notice hidden empty-status" role="status"></div>
        <p class="privacy-note"><span>⌾</span> Your wallet stays private and under your control.</p>
      </section>

      <section class="success-view hidden" data-view="success">
        <header class="success-header"><span class="success-mark">✓</span><p class="eyebrow">Wallet ready</p><h1>New wallet created</h1><p>Your wallet is ready. Save the details below before you continue.</p></header>
        <div class="detail-card"><span class="detail-label">Node ID</span><div class="detail-value node-id-value"></div><button class="text-button" data-action="copy-node-id">Copy node ID</button></div>
        <div class="mnemonic-card">
          <div class="section-heading"><div><span class="step-label">Secret recovery phrase</span><h2>Save these 12 words</h2></div><span class="secret-badge">Private</span></div>
          <p class="mnemonic-warning">Anyone with these words can control this wallet. Store them offline and never share them.</p>
          <textarea class="mnemonic-text" readonly></textarea>
          <div class="button-row"><button class="secondary-button" data-action="copy-mnemonic">Copy phrase</button><button class="secondary-button" data-action="download-mnemonic">Save phrase</button></div>
          <div class="inline-status hidden success-copy-status" role="status"></div>
        </div>
        <button class="primary-button" data-action="finish">Done</button>
      </section>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const sendUp = protocol ? protocol(receiveFromParent) : null
  let currentMnemonic = ''
  let currentNodeId = ''
  let walletState = 'loading'
  const saved = { mnemonic: false, scb: false }

  await sdb.watch(onbatch)
  shadow.addEventListener('click', handleClick)

  el.open = function () {
    closeExpandableSections()
    if (walletState === 'empty') return showView('empty')
    showView(walletState === 'loaded' ? 'loaded' : 'loading')
    request({ type: 'get_wallet_setup_details' })
  }

  request({ type: 'get_wallet_setup_details' })
  return el

  async function handleClick(event) {
    const target = event.target.closest('[data-action]')
    if (!target) return
    const action = target.dataset.action

    if (action === 'toggle-mnemonic') {
      toggleDetail(target, shadow.querySelector('.mnemonic-detail'))
      if (!currentMnemonic) request({ type: 'get_wallet_recovery_phrase' })
    }
    if (action === 'toggle-drain') toggleDetail(target, shadow.querySelector('.drain-detail'))
    if (action === 'download-scb') {
      setButtonLoading(target, true, 'Preparing channel backup…')
      request({ type: 'export_wallet_scb' })
    }
    if (action === 'copy-mnemonic') {
      const copied = await copyText(currentMnemonic)
      if (copied) markSaved('mnemonic')
      showMnemonicStatus(copied ? 'Recovery phrase copied.' : 'Unable to copy the recovery phrase.', copied ? 'success' : 'error')
    }
    if (action === 'download-mnemonic') {
      if (!currentMnemonic) return
      downloadBlob('flamingo-wallet-recovery-phrase.txt', new Blob([currentMnemonic + '\n'], { type: 'text/plain;charset=utf-8' }))
      markSaved('mnemonic')
      showMnemonicStatus('Recovery phrase saved.', 'success')
    }
    if (action === 'drain-funds') {
      const address = shadow.querySelector('.address-input').value.trim()
      showStatus(shadow.querySelector('.drain-status'), address ? 'The drain action is ready for backend connection.' : 'Enter the safe Bitcoin address where funds should be sent.', address ? 'info' : 'error')
    }
    if (action === 'show-delete') shadow.querySelector('.delete-confirmation').classList.remove('hidden')
    if (action === 'cancel-delete') shadow.querySelector('.delete-confirmation').classList.add('hidden')
    if (action === 'confirm-delete') {
      // UI-only state transition. Wallet deletion will be connected to the backend later.
      walletState = 'empty'
      currentMnemonic = ''
      currentNodeId = ''
      saved.mnemonic = false
      saved.scb = false
      resetLoadedView()
      showView('empty')
    }
    if (action === 'create-wallet') {
      setButtonLoading(target, true, 'Creating wallet…')
      showStatus(shadow.querySelector('.empty-status'), 'Creating a fresh wallet and recovery phrase…', 'info')
      request({ type: 'create_new_wallet' })
    }
    if (action === 'import-wallet') showStatus(shadow.querySelector('.empty-status'), 'Wallet import will open here when the import screen is added.', 'info')
    if (action === 'copy-node-id') {
      const originalLabel = target.textContent
      const copied = await copyText(currentNodeId)
      target.textContent = copied ? 'Copied' : 'Copy failed'
      window.setTimeout(function () { target.textContent = originalLabel }, 1600)
    }
    if (action === 'finish') {
      walletState = 'loaded'
      showView('loaded')
      request({ type: 'get_wallet_setup_details' })
    }
  }

  function receiveFromParent(message) {
    const data = message?.data || {}
    if (message?.type === 'wallet_setup_details_loaded') {
      if (walletState === 'empty') return
      if (data.status === 'success') {
        walletState = 'loaded'
        const alias = shadow.querySelector('.current-wallet-alias')
        const nodeId = shadow.querySelector('.current-node-id')
        alias.textContent = data.alias || 'Lightning wallet'
        alias.title = data.alias || ''
        currentNodeId = data.nodeId || ''
        nodeId.textContent = currentNodeId || 'Node ID unavailable'
        nodeId.title = currentNodeId
        showView('loaded')
      } else {
        walletState = 'empty'
        showView('empty')
      }
    }
    if (message?.type === 'wallet_recovery_phrase_loaded') {
      const status = shadow.querySelector('.mnemonic-status')
      if (data.status !== 'success' || !data.mnemonic) return showStatus(status, data.error || 'The recovery phrase is unavailable for this wallet.', 'error')
      currentMnemonic = data.mnemonic.trim()
      renderMnemonic()
      shadow.querySelectorAll('.mnemonic-action').forEach(function (button) { button.disabled = false })
      hideStatus(status)
    }
    if (message?.type === 'wallet_scb_exported') {
      const button = shadow.querySelector('[data-action="download-scb"]')
      setButtonLoading(button, false)
      if (data.status !== 'success') return showStatus(shadow.querySelector('.scb-status'), data.error || 'Unable to export the channel backup.', 'error')
      try {
        const bytes = hexToBytes(data.hex)
        downloadBlob(data.filename || 'emergency.recover', new Blob([bytes], { type: 'application/octet-stream' }))
        markSaved('scb')
        showStatus(shadow.querySelector('.scb-status'), 'Channel backup downloaded successfully.', 'success')
      } catch (error) { showStatus(shadow.querySelector('.scb-status'), error.message, 'error') }
    }
    if (message?.type === 'new_wallet_created') {
      const button = shadow.querySelector('[data-action="create-wallet"]')
      setButtonLoading(button, false)
      if (data.status !== 'success' || !data.mnemonic || !data.nodeId) return showStatus(shadow.querySelector('.empty-status'), data.error || 'The wallet could not be created.', 'error')
      currentMnemonic = data.mnemonic.trim()
      currentNodeId = data.nodeId
      walletState = 'loaded'
      saved.mnemonic = false
      saved.scb = false
      renderWalletDetails()
      hideStatus(shadow.querySelector('.empty-status'))
      showView('success')
    }
  }

  function toggleDetail(button, detail) {
    const opening = detail.classList.contains('hidden')
    detail.classList.toggle('hidden', !opening)
    button.setAttribute('aria-expanded', opening ? 'true' : 'false')
    const chevron = button.querySelector('.chevron')
    if (chevron) chevron.classList.toggle('rotated', opening)
  }

  function closeExpandableSections() {
    shadow.querySelectorAll('.option-detail').forEach(function (detail) { detail.classList.add('hidden') })
    shadow.querySelectorAll('[aria-expanded]').forEach(function (button) {
      button.setAttribute('aria-expanded', 'false')
      const chevron = button.querySelector('.chevron')
      if (chevron) chevron.classList.remove('rotated')
    })
  }

  function markSaved(type) {
    saved[type] = true
    const selector = type === 'mnemonic' ? '.mnemonic-option .option-state' : '.scb-option .option-state'
    shadow.querySelector(selector).classList.remove('hidden')
    updateBackupAdvice()
  }

  function updateBackupAdvice() {
    const total = Number(saved.mnemonic) + Number(saved.scb)
    shadow.querySelector('.progress-label').textContent = `${total} of 2 saved`
    const advice = shadow.querySelector('.backup-advice')
    if (total === 2) {
      advice.classList.add('backups-complete')
      advice.querySelector('span').textContent = '✓'
      advice.querySelector('p').innerHTML = '<strong>Recovery details saved.</strong> Keep both backups somewhere private and secure.'
    } else {
      advice.classList.remove('backups-complete')
      advice.querySelector('span').textContent = '!'
      advice.querySelector('p').innerHTML = '<strong>Back up before you exit.</strong> Save your recovery phrase and channel backup so you can recover later.'
    }
  }

  function resetLoadedView() {
    closeExpandableSections()
    shadow.querySelector('.delete-confirmation').classList.add('hidden')
    shadow.querySelectorAll('.option-state').forEach(function (state) { state.classList.add('hidden') })
    shadow.querySelectorAll('.inline-status').forEach(hideStatus)
    shadow.querySelectorAll('.mnemonic-text').forEach(function (field) { field.value = '' })
    shadow.querySelectorAll('.mnemonic-action').forEach(function (button) { button.disabled = true })
    shadow.querySelector('.address-input').value = ''
    updateBackupAdvice()
  }

  function renderWalletDetails() {
    shadow.querySelectorAll('.node-id-value').forEach(function (node) { node.textContent = currentNodeId })
    renderMnemonic()
  }
  function renderMnemonic() { shadow.querySelectorAll('.mnemonic-text').forEach(function (field) { field.value = currentMnemonic }) }
  function showMnemonicStatus(message, type) { shadow.querySelectorAll('.mnemonic-status, .success-copy-status').forEach(function (target) { showStatus(target, message, type) }) }
  function showView(view) {
    shadow.querySelectorAll('[data-view]').forEach(function (section) { section.classList.toggle('hidden', section.dataset.view !== view) })
    shadow.querySelector('.wallet-setup').scrollTop = 0
  }
  function request(message) { if (typeof sendUp === 'function') sendUp({ from: 'wallet_setup', ...message }) }
  function setButtonLoading(button, loading, label) {
    if (!button) return
    if (loading) {
      button.dataset.originalLabel = button.innerHTML
      button.textContent = label
      button.disabled = true
      button.classList.add('loading')
    } else {
      if (button.dataset.originalLabel) button.innerHTML = button.dataset.originalLabel
      delete button.dataset.originalLabel
      button.disabled = false
      button.classList.remove('loading')
    }
  }
  function showStatus(target, message, type) {
    if (!target) return
    target.textContent = message
    target.className = target.className.replace(/\s(status-info|status-success|status-error)/g, '')
    target.classList.add(`status-${type}`)
    target.classList.remove('hidden')
  }
  function hideStatus(target) { target.classList.add('hidden'); target.textContent = '' }
  function hexToBytes(hex) {
    if (!hex || hex.length % 2 !== 0 || !/^[0-9a-f]+$/i.test(hex)) throw new Error('The backend returned an invalid SCB file.')
    const bytes = new Uint8Array(hex.length / 2)
    for (let i = 0; i < hex.length; i += 2) bytes[i / 2] = parseInt(hex.slice(i, i + 2), 16)
    return bytes
  }
  function downloadBlob(filename, blob) {
    const url = window.URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = filename
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
    window.URL.revokeObjectURL(url)
  }
  async function copyText(text) {
    if (!text) return false
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) await navigator.clipboard.writeText(text)
      else {
        const textarea = document.createElement('textarea')
        textarea.value = text
        document.body.appendChild(textarea)
        textarea.select()
        document.execCommand('copy')
        textarea.remove()
      }
      return true
    } catch (error) { return false }
  }
  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(function (path) { return drive.get(path).then(function (file) { return file.raw }) }))
      const func = on[type] || fail
      await func(data, type)
    }
  }
  function inject(data) { style.textContent = data[0] }
  function ondata(data) { }
  function onicons(data) { }
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return {
    api: fallback_instance,
    _: { 'input_field': { $: '' }, 'button': { $: '' } }
  }
  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    return {
      drive: {
        'icons/': { 'x.svg': { '$ref': 'x.svg' } },
        'style/': { 'details_menu.css': { '$ref': 'details_menu.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      },
      _: {
        input_field: {
          mapping: { style: 'style', data: 'data', icons: 'icons' },
          0: {
            placeholder: '1BoatSLRHtKNngkdXEeobR76b53LETtpyT',
            address: '1BoatSLRHtKNngkdXEeobR76b53LETtpyT',
            icon: 'apple'
          }
        },
        button: {
          mapping: { style: 'style', data: 'data' },
          1: { label: 'Reveal' }
        }
      }
    }
  }
}
